// Vite config for the AI十项全能 site. Every page is generated by the route
// plugin in scripts/routes.mjs from pages/<type>.html and data/*.json.
// Site project contract (website/README.md): the base path comes from ONESHOT_SITE_BASE
// (/<topic id>/ on the domain; publish.py sets it), the data folder from ONESHOT_SITE_DATA_DIR.
// The dev server without ONESHOT_SITE_BASE serves the site at /.
import { defineConfig } from 'vite';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { routePlugin } from './scripts/routes.mjs';

const root = dirname(fileURLToPath(import.meta.url));

function siteBase(command) {
  const base = process.env.ONESHOT_SITE_BASE?.trim();
  if (!base) {
    if (command === 'build') throw new Error('ONESHOT_SITE_BASE 没有设置：构建须给出站内根路径（如 /decathlon/），由 website/tools/publish.py 传入');
    return '/';
  }
  if (!/^\/(?:[a-z0-9]+(?:-[a-z0-9]+)*\/)*$/.test(base)) throw new Error(`ONESHOT_SITE_BASE 应写成 /<专题 id>/，现在是 ${base}`);
  return base;
}

export default defineConfig(({ command }) => ({
  root,
  base: siteBase(command),
  appType: 'mpa',
  publicDir: 'public',
  plugins: [routePlugin({ root })],
  server: { port: 5180, strictPort: false },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    target: 'es2022',
    assetsInlineLimit: 0,
    chunkSizeWarningLimit: 900,
  },
}));
